import { objective, threadChoices } from './objective-model.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const pinButton=key=>`<button type="button" class="text-button thread-pin" data-action="pin-thread" data-id="${esc(key)}">Pin this thread</button>`;
export function threadMarkup(state) {
  const goal=objective(state),last=objective(state,state.thread?.last),active=goal||last;
  const extra=goal&&!threadChoices.some(([id])=>id===goal.key)?`<option value="${esc(goal.key)}" selected>${esc(goal.title)}</option>`:'';
  return `<div class="thread-line"><span aria-hidden="true" class="thread-knot">${active?.done?'✓':'⌁'}</span><div><strong>${esc(active?.title||'One thread to follow')}</strong><span>${esc(goal?goal.done?'A promise kept. Choose another whenever you like.':goal.next?.detail:last?'Your place is saved. Continue whenever you like.':'Choose something you would like to work toward.')}</span></div>${active?.next?`<a class="thread-next" href="#${esc(active.next.route)}">${esc(goal?active.next.label:'Return to your work')} →</a>`:''}<details class="thread-chooser"><summary>${goal?'Change thread':'Choose a thread'}</summary><div><label for="thread-choice">Something to work toward</label><select id="thread-choice"><option value="">No pinned thread</option>${extra}${threadChoices.map(([id,label])=>`<option value="${id}" ${state.thread?.goal===id?'selected':''}>${esc(label)}</option>`).join('')}</select><button type="button" class="button outline" data-action="choose-thread">Follow this thread</button>${goal?`<p>${goal.count}/${goal.total} steps complete</p>`:''}${last?.next?`<p>Last worked on: <a href="#${esc(last.next.route)}">${esc(last.title)}</a>. Your progress and drafts are saved.</p>`:'<p>There is no rush. You can change your mind at any time.</p>'}</div></details></div>`;
}
